"use strict";(self.webpackChunkrrbtc_wiki_docusaurus=self.webpackChunkrrbtc_wiki_docusaurus||[]).push([[86326],{38056(e){e.exports=JSON.parse('{"tag":{"label":"hardware-wallet","permalink":"/tags/hardware-wallet","allTagsPath":"/tags","count":11,"items":[{"id":"entities/coldcard","title":"ColdCard","description":"ColdCard is a hardware wallet for advanced users prioritizing security verification, air-gapped signing, and open-source principles. Manufactured by Coinkite, widely used in multisig setups.","permalink":"/entities/coldcard"},{"id":"concepts/custody-models","title":"Custody Models","description":"The spectrum of bitcoin custody ranges from full self-custody to fully custodial exchange wallets. The right model depends on technical ability, threat model, and need for inheritance or recovery.","permalink":"/concepts/custody-models"},{"id":"entities/hwi","title":"HWI (Hardware Wallet Interface)","description":"Command-line tool and Python library for connecting hardware wallets to Bitcoin Core. Enables direct signing with devices like Trezor, Ledger, and Coldcard without trusting intermediary software.","permalink":"/entities/hwi"},{"id":"entities/jade-diy","title":"Jade DIY","description":"Jade DIY is Blockstream\'s open-source firmware for the Blockstream Jade hardware wallet, made available for installation on compatible off-the-shelf hardware. The project lets users build and verify their own Jade-compatible signing device from generic components.","permalink":"/entities/jade-diy"},{"id":"entities/krux","title":"Krux","description":"Krux is open-source firmware that enables anyone to build a Bitcoin signing device from off-the-shelf parts. It runs on cheap, general-purpose microcontrollers (e.g. M5StickV, Maix Amigo, Maix Dock) and turns them into air-gapped signing devices.","permalink":"/entities/krux"},{"id":"entities/ledger","title":"Ledger","description":"Ledger is a hardware wallet manufacturer using secure element (SE) chips to protect private keys. One of the most widely sold hardware wallets globally.","permalink":"/entities/ledger"},{"id":"concepts/multisig","title":"Multisig","description":"Deep dive into n-of-m multisignature schemes, hardware wallet coordination, deterministic wallets (BIP-85), and popular multisig coordinators (Sparrow, Nunchuk, CARAVAN).","permalink":"/concepts/multisig"},{"id":"entities/seedsigner","title":"SeedSigner","description":"Open-source, DIY Bitcoin signing device built from commodity hardware. Designed for air-gapped seed generation, transaction signing, and multisig coordination without trusting proprietary hardware.","permalink":"/entities/seedsigner"},{"id":"entities/specter-diy","title":"Specter DIY","description":"Specter DIY is an open-source, do-it-yourself hardware wallet project from the Specter suite. It turns commodity hardware into an air-gapped signing device that pairs with Specter Desktop for multisig and single-sig custody.","permalink":"/entities/specter-diy"},{"id":"entities/trezor","title":"Trezor","description":"Trezor is a hardware wallet developed by SatoshiLabs. The first commercial hardware wallet (2014), known for fully open-source firmware.","permalink":"/entities/trezor"},{"id":"queries/which-custody-model-fits-my-threat-model","title":"Which Custody Model Fits My Threat Model?","description":"Decision framework for choosing between single-sig, multisig, collaborative custody, and custodial solutions mapped to specific threat models and capability levels.","permalink":"/queries/which-custody-model-fits-my-threat-model"}],"unlisted":false}}')}}]);